'use client'

export type Filters = {
  maxPrice: number
  sortBy: 'newest' | 'price_low' | 'price_high'
}

export function FilterSheet({
  filters,
  onChange,
  onClose,
}: {
  filters: Filters
  onChange: (filters: Filters) => void
  onClose: () => void
}) {
  return (
    <div className="fixed inset-0 bg-black/40 flex items-end z-50" onClick={onClose}>
      <div
        className="bg-white w-full rounded-t-2xl p-5"
        onClick={(e) => e.stopPropagation()}
      >
        <h3 className="font-semibold mb-4">Filters</h3>

        <label className="text-sm text-gray-600">
          Max price: ${filters.maxPrice}
        </label>
        <input
          type="range"
          min={0}
          max={100}
          value={filters.maxPrice}
          onChange={(e) =>
            onChange({ ...filters, maxPrice: Number(e.target.value) })
          }
          className="w-full mb-4"
        />

        <p className="text-sm text-gray-600 mb-2">Sort by</p>
        <div className="flex gap-2 mb-4">
          {(['newest', 'price_low', 'price_high'] as const).map((opt) => (
            <button
              key={opt}
              onClick={() => onChange({ ...filters, sortBy: opt })}
              className={`px-3 py-2 rounded-lg text-sm ${
                filters.sortBy === opt
                  ? 'bg-black text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}
            >
              {opt === 'newest'
                ? 'Newest'
                : opt === 'price_low'
                ? 'Price: Low'
                : 'Price: High'}
            </button>
          ))}
        </div>

        <button
          onClick={onClose}
          className="w-full bg-black text-white rounded-xl py-3 font-medium"
        >
          Apply
        </button>
      </div>
    </div>
  )
}
